 async Task FieldKitCoopChecks(CoopActor actor){var oldCraft=Json.Write(actor.Game.Craft);var hostStock=game.Craft.ThrowStock.ToArray();try{EnterDungeon(HeartDungeon());ClearEnemies();player.Position=new(6,.1f,1);actor.Body.Position=new(0,.1f,0);actor.Game.Craft.Weapons.Add(19);actor.Game.Craft.Weapon=19;actor.Game.Craft.ArrowType=0;actor.Game.Craft.ArrowStock[3]=3;actor.Game.Craft.ThrowStock[5]=1;actor.Game.Craft.ThrowStock[0]=0;actor.Game.Craft.Glass=2;actor.Game.Craft.Fuel=10;actor.Game.Craft.Materials[2]=10;actor.Game.Craft.UnlockedTier=5;actor.Shot=actor.Reload=0;actor.Game.Shield=50;fieldCoopAck=false;
  AddEnemy("field-kit/coop-target",0,-6,1);var target=infected.Single();target.Hp=target.MaxHp=1000;target.BossState="";target.Stagger=30;SendCoopPersonal(actor.Id,CoopProfileJson(actor.Game),"",actor.Body.Position,true);RpcId(actor.Id,nameof(CoopCheckStage),"field-kit",actor.Body.Position);
  await CoopWait(()=>fieldCoopAck,"Guest arrow payload, smoke or crafting failed",25);MigrationChecks.Assert(target.Hp<1000&&actor.Game.Craft.ArrowStock[3]==2,"Host resolves guest selected arrow and private cost");MigrationChecks.Assert(actor.Game.Craft.ThrowStock[5]==0&&game.Craft.ThrowStock.SequenceEqual(hostStock)&&fieldAreas.Any(a=>a.Kind==5),"Thrown smoke is shared; inventory is private");MigrationChecks.Assert(actor.Game.Craft.Glass==1&&actor.Game.Craft.Fuel==8&&actor.Game.Craft.ThrowStock[0]==1,"Actual guest Molotov recipe conserves bottle and fuel");GD.Print("PASS / two-process field kit: selected iron arrow, physical projectile damage, private ammo, shared colored smoke, replicated volumes and host-validated glass/fuel Molotov crafting");
 }finally{foreach(var area in fieldAreas)area.Model?.QueueFree();fieldAreas.Clear();foreach(var f in fieldFlights)f.Model?.QueueFree();fieldFlights.Clear();fieldBurns.Clear();fieldLured.Clear();fieldStuns.Clear();ClearEnemies();actor.Game.Profile.Crafting=Json.Read<ExpeditionCraftState>(oldCraft);ExitDungeon();Teleport(0,12);actor.Body.Position=HostPosition+Vector3.Right*3;SendCoopPersonal(actor.Id,CoopProfileJson(actor.Game),"Field kit checks complete",actor.Body.Position,true);}}
 async Task ClientFieldKitChecks(Vector3 at){await CoopWait(()=>InHeartRoom&&infected.Any(e=>e.Id=="field-kit/coop-target"),"Field-kit target missing");CoopRequest("fieldkit","arrow|3");await CoopWait(()=>game.Craft.ArrowType==3,"Arrow selection not synchronized");var target=infected.Single(e=>e.Id=="field-kit/coop-target");await AimCoopFixture(target,1.0f);CoopRequest("shoot");await CoopWait(()=>game.Craft.ArrowStock[3]==2&&target.Hp<1000,"Iron arrow result missing");CoopRequest("fieldkit","throw|5");await CoopWait(()=>game.Craft.Throwable==5,"Throwable selection missing");await CoopDelay(1.1);CoopRequest("fieldthrow");await CoopWait(()=>fieldAreas.Any(a=>a.Kind==5)&&game.Craft.ThrowStock[5]==0,"Colored smoke or private consumption missing",12);int index=Array.FindIndex(ExpeditionRecipe.All,r=>r.Kind=="fieldkit"&&FieldRecipe.All[r.Result].Kind=="throw"&&FieldRecipe.All[r.Result].Result==0);CoopRequest("fieldkit","craft|"+index);await CoopWait(()=>game.Craft.ThrowStock[0]==1&&game.Craft.Glass==1&&game.Craft.Fuel==8,"Early Molotov crafting result missing");RpcId(1,nameof(CoopFieldKitAck));}
